package main

import (
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	a := make([]int64, n)
	for i := range a {
		a[i] = num()
	}
	m := int(num())
	b := make([]int64, m)
	for i := range b {
		b[i] = num()
	}
	// Least significant digit first: add column by column with a carry.
	digits := []int64{}
	var carry int64
	for i := 0; i < max(n, m); i++ {
		total := carry
		if i < n {
			total += a[i]
		}
		if i < m {
			total += b[i]
		}
		digits = append(digits, total%10)
		carry = total / 10
	}
	if carry > 0 {
		digits = append(digits, carry)
	}
	for len(digits) > 1 && digits[len(digits)-1] == 0 { // drop leading zeros of the sum
		digits = digits[:len(digits)-1]
	}
	out := []byte{}
	for i, d := range digits {
		if i > 0 {
			out = append(out, ' ')
		}
		out = append(out, byte('0'+d))
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
